package com.mediconnect.doctor.api;
import java.util.List; import java.util.UUID; import com.mediconnect.doctor.application.DoctorService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/doctors") @Tag(name="Doctors") @SecurityRequirement(name="bearerAuth") public class DoctorController { private final DoctorService service; public DoctorController(DoctorService service){this.service=service;} @GetMapping @Operation(summary="List doctors by specialty",description="Authenticated doctor catalog. Redis is used in production and in-memory cache in development.") public List<DoctorResponse> listBySpecialty(@RequestParam UUID specialtyId){return service.listBySpecialty(specialtyId);} }
